import * as React from 'react';
import { cn } from '@/lib/utils';
import { Container, type ContainerWidth } from '../container/Container';

export type SectionTone = 'default' | 'muted' | 'subtle' | 'brand' | 'inverse';

export type SectionProps = React.HTMLAttributes<HTMLElement> & {
  /** Surface treatment. 'inverse' flips the token ladder for a dark band. */
  tone?: SectionTone;
  /** Vertical rhythm. Default 'md'. */
  padding?: 'none' | 'sm' | 'md' | 'lg' | 'xl';
  /** Inner container width. Default 'lg'. */
  width?: ContainerWidth;
  /** Wrap children in a centered Container (default true). */
  container?: boolean;
  /** Extra classes for the inner Container. */
  containerClassName?: string;
  /** Semantic element (default 'section'). */
  as?: 'section' | 'div' | 'article' | 'header' | 'footer' | 'main' | 'aside';
};

const toneClasses: Record<SectionTone, string> = {
  default: 'bg-background text-foreground',
  muted: 'bg-muted/40 text-foreground',
  subtle: 'bg-secondary/50 text-secondary-foreground',
  brand: 'bg-primary text-primary-foreground',
  inverse: 'bg-inverse text-inverse-foreground',
};

const paddingClasses = {
  none: '',
  sm: 'py-10 sm:py-12',
  md: 'py-14 sm:py-16',
  lg: 'py-16 sm:py-20 lg:py-24',
  xl: 'py-20 sm:py-28 lg:py-32',
} as const;

/**
 * Scope the semantic token ladder to an inverse band. Components inside the
 * Section (Card, Text, FormField, SectionHeading) read the scoped variables,
 * so a dark band does not require per-child color overrides.
 */
const inverseVars = {
  '--background': 'var(--inverse)',
  '--foreground': 'var(--inverse-foreground)',
  '--muted': 'var(--inverse-muted)',
  '--muted-foreground': 'var(--inverse-muted-foreground)',
  '--border': 'var(--inverse-border)',
  '--input': 'var(--inverse-border)',
  '--ring': 'var(--inverse-primary)',
  '--primary': 'var(--inverse-primary)',
  '--primary-foreground': 'var(--inverse-primary-foreground)',
  '--card': 'var(--inverse-card)',
  '--card-foreground': 'var(--inverse-card-foreground)',
  '--popover': 'var(--inverse-card)',
  '--popover-foreground': 'var(--inverse-card-foreground)',
  '--secondary': 'var(--inverse-muted)',
  '--secondary-foreground': 'var(--inverse-foreground)',
  '--accent': 'var(--inverse-muted)',
  '--accent-foreground': 'var(--inverse-foreground)',
} as React.CSSProperties;

const brandVars = {
  '--foreground': 'var(--primary-foreground)',
  '--muted-foreground': 'var(--primary-foreground)',
  '--border': 'var(--primary-foreground)',
  '--input': 'var(--primary-foreground)',
} as React.CSSProperties;

/**
 * Page section with a consistent vertical rhythm and surface tone. Section
 * owns the full-bleed band; Container owns the gutters. Use it instead of
 * repeating `py-*` and background classes on every marketing or content
 * section, and use `tone="inverse"` for a readable dark band.
 */
export const Section = React.forwardRef<HTMLElement, SectionProps>(function Section(
  {
    tone = 'default',
    padding = 'md',
    width = 'lg',
    container = true,
    containerClassName,
    as = 'section',
    className,
    style,
    children,
    ...props
  },
  ref
) {
  const Tag = as as 'section';
  const toneStyle = tone === 'inverse' ? inverseVars : tone === 'brand' ? brandVars : undefined;

  return (
    <Tag
      ref={ref as never}
      data-tone={tone === 'default' ? undefined : tone}
      className={cn('w-full', toneClasses[tone], paddingClasses[padding], className)}
      style={{ ...toneStyle, ...style }}
      {...props}
    >
      {container ? (
        <Container width={width} className={containerClassName}>
          {children}
        </Container>
      ) : (
        children
      )}
    </Tag>
  );
});

{
  "id": "section",
  "name": "Section",
  "tier": "organism",
  "package": "@slipstream-ui/core",
  "importPath": "@slipstream-ui/core",
  "version": "0.6.0",
  "sourceDir": "section",
  "exportName": "Section",
  "description": "Full-width page section with a surface tone, vertical rhythm and an optional centered container.",
  "designIntent": "Marketing and content pages alternate background bands and vertical padding. Section owns the band and the inner container so pages stop repeating py-* and background classes, and tone=\"inverse\" scopes the token ladder for a readable dark band.",
  "props": [
    {
      "name": "tone",
      "type": "'default' | 'muted' | 'subtle' | 'brand' | 'inverse'",
      "required": false,
      "defaultValue": "default",
      "enum": [
        "default",
        "muted",
        "subtle",
        "brand",
        "inverse"
      ],
      "description": "Surface treatment. inverse flips background, foreground, card, border and muted tokens for its subtree."
    },
    {
      "name": "padding",
      "type": "'none' | 'sm' | 'md' | 'lg' | 'xl'",
      "required": false,
      "defaultValue": "md",
      "enum": [
        "none",
        "sm",
        "md",
        "lg",
        "xl"
      ],
      "description": "Vertical rhythm. md is py-14 / sm:py-16."
    },
    {
      "name": "width",
      "type": "'sm' | 'md' | 'lg' | 'xl' | 'full'",
      "required": false,
      "defaultValue": "lg",
      "enum": [
        "sm",
        "md",
        "lg",
        "xl",
        "full"
      ],
      "description": "Inner Container width."
    },
    {
      "name": "container",
      "type": "boolean",
      "required": false,
      "defaultValue": "true",
      "description": "Wrap children in a centered Container."
    },
    {
      "name": "containerClassName",
      "type": "string",
      "required": false,
      "description": "Extra classes for the inner Container."
    },
    {
      "name": "as",
      "type": "'section' | 'div' | 'article' | 'header' | 'footer' | 'main' | 'aside'",
      "required": false,
      "defaultValue": "section",
      "description": "Semantic element to render."
    }
  ],
  "examples": [
    {
      "title": "Inverse CTA band",
      "code": "<Section tone=\"inverse\" padding=\"lg\">\n  <SectionHeading title=\"Ready to exit?\" align=\"center\" />\n</Section>",
      "description": "A dark band whose child components inherit inverse surface tokens."
    },
    {
      "title": "Muted feature band",
      "code": "<Section tone=\"muted\" width=\"xl\">\n  <FeatureGrid />\n</Section>",
      "description": "A tinted band with a wider content cap."
    }
  ],
  "antiPatterns": [
    {
      "title": "Don't put a Section inside a Section",
      "explanation": "Nesting bands doubles padding and can reset the tone. Use one Section per band and plain layout elements inside it.",
      "example": "// Avoid\n<Section><Section>Content</Section></Section>"
    },
    {
      "title": "Don't hardcode colors inside a tone",
      "explanation": "Use semantic tokens so the inverse scope can flip card, border and muted text automatically.",
      "example": "// Avoid\n<Section tone=\"inverse\"><div className=\"bg-slate-900 text-white\" /></Section>"
    }
  ],
  "accessibility": [
    {
      "feature": "Tone scoping",
      "implementation": "tone=inverse sets background, foreground, card, border and muted CSS variables on the section",
      "userRequirements": "Keep text and controls on semantic tokens so contrast survives the tone change"
    },
    {
      "feature": "Landmark",
      "implementation": "Renders a section element by default",
      "userRequirements": "Add aria-label or aria-labelledby when the section is a named region"
    }
  ],
  "contentGuidelines": [
    {
      "contentType": "Section rhythm",
      "guidelines": [
        "One idea per band",
        "Alternate default and muted tones",
        "Use inverse once per page for the final CTA"
      ],
      "goodExamples": [
        "Default features, muted proof, inverse CTA"
      ],
      "badExamples": [
        "Five alternating dark bands in a row"
      ]
    }
  ],
  "compositionRules": [
    {
      "component": "Container",
      "relationship": "Section renders Container when container is true",
      "example": "<Section width=\"lg\"><Hero /></Section>"
    },
    {
      "component": "Hero",
      "relationship": "Hero is placed inside Section; Section owns the band",
      "example": "<Section tone=\"inverse\"><Hero title=\".\" /></Section>"
    }
  ],
  "relatedComponents": [
    "Container",
    "Hero",
    "CTASection",
    "PageHeader"
  ]
}
